-- =============================================================================
-- Admin-editable legal pages (2026-10-29)
--
-- PrivacyPolicy.tsx and StoreRules.tsx hardcoded their section text, so every
-- wording change needed a code deploy. One row per page; `sections` is an
-- ordered array of { id, title, body: string[], bullets?: string[] } — the same
-- shape the pages already rendered. Seeded from the previous hardcoded text.
-- =============================================================================

create table public.legal_pages (
  slug text primary key check (slug in ('privacy_policy', 'store_rules')),
  intro text not null,
  revision_date text not null,
  sections jsonb not null default '[]'::jsonb check (jsonb_typeof(sections) = 'array'),
  updated_at timestamptz not null default now()
);

alter table public.legal_pages enable row level security;

create policy "legal_pages_public_read" on public.legal_pages
  for select to public using (true);
create policy "legal_pages_admin_insert" on public.legal_pages
  for insert with check (((((select auth.jwt()) -> 'app_metadata') ->> 'role') = 'admin'));
create policy "legal_pages_admin_update" on public.legal_pages
  for update using (((((select auth.jwt()) -> 'app_metadata') ->> 'role') = 'admin'))
  with check (((((select auth.jwt()) -> 'app_metadata') ->> 'role') = 'admin'));
create policy "legal_pages_admin_delete" on public.legal_pages
  for delete using (((((select auth.jwt()) -> 'app_metadata') ->> 'role') = 'admin'));

insert into public.legal_pages (slug, intro, revision_date, sections) values
  ('privacy_policy', $intro$Šiame puslapyje pateikiama informacija apie tai, kokius asmens duomenis tvarko BRICKTIME, kokiais tikslais jie naudojami, kiek laiko saugomi ir kaip galite įgyvendinti savo teises.$intro$, '2026-07-16', $json$[{"id":"bendra","title":"Bendroji informacija","body":["Ši privatumo politika nustato MB „Brick time“, juridinio asmens kodas 307611342, buveinės adresas Pasakų g. 10-1, Vilnius, elektroninio pašto adresas info@bricktime.lt, vykdomo interneto svetainės www.bricktime.lt lankytojų ir kitų duomenų subjektų asmens duomenų tvarkymo sąlygas bei su tuo susijusių teisių įgyvendinimo tvarką.","Valdytojas gali bet kuriuo metu peržiūrėti ir pakeisti privatumo politiką, todėl rekomenduojama periodiškai patikrinti aktualią jos redakciją. Interneto svetainės lankytojų asmens duomenys tvarkomi vadovaujantis galiojančiais teisės aktais ir taikant tinkamas technines bei organizacines apsaugos priemones.","Jūsų duomenys naudojami tik šioje privatumo politikoje nurodytais tikslais. Jie gali būti perduodami Valdytojo duomenų tvarkytojams, teikiantiems interneto svetainės talpinimo ir priežiūros paslaugas, o įstatymų numatytais atvejais ir kompetentingoms valdžios institucijoms.","Svetainėje gali būti nuorodų į trečiųjų šalių interneto svetaines. Už šių svetainių privatumo praktikas Valdytojas neatsako, todėl rekomenduojama susipažinti ir su jų privatumo politikomis."]},{"id":"slapukai","title":"Slapukų naudojimas","body":["Interneto svetainėje naudojami slapukai padeda užtikrinti tinkamą svetainės veikimą, optimalų greitį bei saugumą, analizuoti lankytojų srautus ir tobulinti naudotojo patirtį.","Naršymo metu gali būti naudojami būtini ir analitiniai slapukai, taip pat trečiųjų šalių, pavyzdžiui, Facebook, Instagram ir TikTok, įskiepiai, į kuriuos taip pat įdiegti slapukai. Informaciją apie konkrečius slapukus galite matyti savo naršyklės nustatymuose.","Slapukus galite apriboti arba užblokuoti savo naršyklėje, tačiau tokiu atveju dalis svetainės funkcijų gali veikti netinkamai arba būti neprieinamos."],"bullets":["Būtinasis slapukas `bricktime_cookie_consent` naudojamas jūsų pasirinkimui dėl slapukų sutikimo įsiminti (galioja 12 mėnesių).","Analitiniai ir rinkodaros slapukai (`_ga`, `ga*`, `_fbp`, `_fbc`) įkeliami tik gavus jūsų sutikimą svetainėje rodomame slapukų pranešime; savo pasirinkimą galite bet kada pakeisti.","Analitiniai duomenys gali apimti IP adresą, įrenginio informaciją, apytikslę geografinę vietą, aplankytus puslapius, sesijos trukmę, paspaudimus ir atėjimo šaltinį.","Daugiau informacijos apie slapukus ir jų valdymą galite rasti adresu `http://www.allaboutcookies.org`."]},{"id":"komunikacija","title":"Komunikacijos tikslu tvarkomi duomenys","body":["Tikslu atsakyti į jūsų užklausą ir išsaugoti komunikacijos įrodymus, Valdytojas tvarko informaciją, kurią pateikiate susisiekdami el. paštu, paštu, per paklausimo formą arba per socialinius tinklus.","Kartu su paklausimais pateikti asmens duomenys bei tolimesnis susirašinėjimas saugomi tiek, kiek reikia konkrečiai užduočiai įvykdyti ir Valdytojo teisėms užtikrinti, bet ne ilgiau kaip 1 metus nuo duomenų gavimo dienos.","Susisiekiant per socialinių tinklų paskyras, jūsų duomenys gali būti atskleisti tų socialinių tinklų valdytojams pagal jų taikomas privatumo taisykles."],"bullets":["El. paštu: el. pašto adresas, laiško data, laikas ir susirašinėjimo turinys.","Paštu: siuntėjo vardas, pavardė, adresas, gavimo data ir laiške nurodyta informacija.","Paklausimo forma: vardas, pavardė, el. pašto adresas, telefono numeris, užklausos data, laikas ir turinys.","Facebook ar Instagram: vartotojo vardas, pavardė ir susirašinėjimo turinys."]},{"id":"paskyra","title":"Registracija ir asmeninės paskyros administravimas","body":["Sukuriant ir administruojant asmeninę paskyrą, duomenys tvarkomi siekiant suteikti galimybę patogiau naudotis Valdytojo paslaugomis ir elektronine parduotuve.","Teisinis šio tvarkymo pagrindas yra jūsų sutikimas susikurti paskyrą. Registracijos ir prisijungimo duomenys saugomi 10 metų nuo paskutinio aktyvaus veiksmo interneto svetainėje arba iki paskyros ištrynimo.","Duomenys, susiję su užsakymais ir prenumeratomis elektroninėje parduotuvėje, saugomi 10 metų nuo užsakymo ar prenumeratos galiojimo pabaigos."],"bullets":["Registracijos metu: vardas, el. pašto adresas, slaptažodis, registracijos data ir laikas.","Prisijungimo metu: el. pašto adresas, slaptažodis, prisijungimų data ir laikas.","Paskyroje: užsakymų ir prenumeratų istorija."]},{"id":"prekyba","title":"Elektroninė prekyba ir sutarčių vykdymas","body":["Tikslu sudaryti ir įvykdyti sutartį bei įvykdyti užsakymą elektroninėje parduotuvėje, Valdytojas tvarko su pirkimu, atsiskaitymu ir pristatymu susijusius pirkėjų asmens duomenis.","Teisinis tvarkymo pagrindas yra siekis įvykdyti pirkimo-pardavimo sutartį. Jei sutartis sudaroma su juridiniu asmeniu, gali būti tvarkomi ir atstovo duomenys.","Šie duomenys saugomi 10 metų nuo užsakymo ar prenumeratos galiojimo pabaigos."],"bullets":["Vardas, pavardė, el. pašto adresas, kontaktinis telefono numeris ir pristatymo adresas.","Mokėjimo data, pasirinktos prenumeratos, kainos, kiekiai, mokėjimo būdas, kita atsiskaitymo informacija, suteiktos nuolaidos ir banko sąskaitos numeris.","Informacija apie pasirinktą pristatymo būdą ir vietą."]},{"id":"atsiliepimai","title":"Atsiliepimų pateikimas ir administravimas","body":["Prisijungęs naudotojas gali palikti atsiliepimą apie Valdytojo teikiamas paslaugas. Svetainėje gali būti rodomas atsiliepimą pateikusio asmens vardas, pavardės pirma raidė ir atsiliepimo turinys.","Teisinis tvarkymo pagrindas yra jūsų sutikimas pateikti atsiliepimą. Atsiliepimai gali būti matomi tol, kol prekiaujama atitinkama paslauga, bet ne ilgiau kaip 10 metų nuo atsiliepimo pateikimo dienos.","Atsiliepimą galite bet kada panaikinti prisijungę prie savo paskyros arba kreipdamiesi į Valdytoją."],"bullets":["Vardas ir pavardė.","Atsiliepimo data ir laikas.","Atsiliepimo turinys."]},{"id":"rinkodara","title":"Tiesioginė rinkodara","body":["Naujienlaiškį galite užsisakyti svetainėje nurodydami savo el. pašto adresą. Tiesioginės rinkodaros tikslu naudojamas tik prenumeratoriaus el. pašto adresas.","Teisinis tvarkymo pagrindas yra jūsų sutikimas gauti naujienlaiškius. Duomenys šiuo tikslu gali būti perduodami marketingo paslaugų teikėjams.","Asmens duomenys tiesioginės rinkodaros tikslu tvarkomi 10 metų nuo prenumeratos pradžios, o informacija apie sutikimą saugoma dar vienerius metus po naujienlaiškių siuntimo pabaigos."],"bullets":["Bet kada galite atsisakyti naujienlaiškio paspausdami atsisakymo nuorodą laiške.","Taip pat galite pateikti atsisakymą el. paštu info@bricktime.lt."]},{"id":"teises","title":"Teisių įgyvendinimo tvarka","body":["Visi asmenys, kurių asmens duomenis tvarko Valdytojas, turi teisę susipažinti su tvarkomais duomenimis, reikalauti juos ištaisyti, apriboti tvarkymą, gauti duomenų perkeliamumą, nesutikti su tvarkymu, reikalauti ištrinti duomenis ir pateikti skundą priežiūros institucijai.","Prašymai dėl šių teisių įgyvendinimo teikiami raštu Valdytojo buveinės adresu arba el. paštu info@bricktime.lt. Kai kuriais atvejais gali būti reikalingas kvalifikuotas elektroninis parašas arba notaro patvirtinta asmens dokumento kopija.","Pagrįsti prašymai vykdomi teisės aktuose ir politikoje nustatytais terminais: pavyzdžiui, duomenų perkeliamumas ir ištrynimas ne vėliau kaip per 30 dienų, o duomenų tvarkymo apribojimas per 5 darbo dienas nuo prašymo gavimo."],"bullets":["Teisė susipažinti su tvarkomais asmens duomenimis.","Teisė reikalauti ištaisyti neteisingus ar netikslius duomenis.","Teisė reikalauti apriboti duomenų tvarkymą.","Teisė į duomenų perkeliamumą.","Teisė nesutikti su duomenų tvarkymu.","Teisė reikalauti ištrinti duomenis.","Teisė paduoti skundą Valstybinei duomenų apsaugos inspekcijai."]}]$json$::jsonb),
  ('store_rules', $intro$Elektroninės parduotuvės BRICKTIME paslaugų užsakymo tvarka ir taisyklės – susipažink prieš užsisakydamas prenumeratą.$intro$, '2026-07-16', $json$[{"id":"bendrosios-nuostatos","title":"1. Bendrosios nuostatos","body":["Šios elektroninės parduotuvės www.bricktime.lt paslaugų užsakymo tvarka ir taisyklės (toliau – „Taisyklės“) nustato bendrąsias naudojimosi BRICKTIME internetine parduotuve www.bricktime.lt sąlygas. Taisyklės yra taikomos, kai Pirkėjas renkasi, užsako ir perka BRICKTIME elektroninėje parduotuvėje siūlomas paslaugas (įsigyja prenumeratą) ar bet kaip kitaip naudojasi BRICKTIME interneto svetainės teikiamomis paslaugomis.","Santykiai, kurių nereglamentuoja šios Taisyklės arba reglamentuoja juos tik iš dalies, reguliuojami Lietuvos Respublikos teisės aktų nustatyta tvarka.","BRICKTIME elektroninėje parduotuvėje paslaugų teikimą organizuoja, vykdo ir su ja susijusias paslaugas Pirkėjui teikia MB „Brick time“, juridinio asmens kodas 307611342, buveinės adresas: Pasakų g. 10-1, Vilnius, tel. +370 682 11695, el. p. info@bricktime.lt (toliau – „Pardavėjas“). BRICKTIME elektroninėje parduotuvėje parduodamos BRICKTIME teikiamos paslaugos – LEGO® rinkinių prenumeratos.","Pirkėju šiose Taisyklėse yra bet kuris asmuo, perkantis BRICKTIME elektroninėje parduotuvėje ar besinaudojantis kitomis BRICKTIME elektroninės parduotuvės paslaugomis. Naudotis BRICKTIME elektronine parduotuve ir joje pirkti turi teisę veiksnūs fiziniai asmenys, ne jaunesni nei 18 metų, ir juridiniai asmenys, veikiantys per įgaliotus atstovus.","Pateikdamas užsakymą (užsisakęs prenumeratą) Pirkėjas besąlygiškai patvirtina, jog jis turi teisę pirkti BRICKTIME elektroninėje parduotuvėje.","Kartu su Pirkėjo pateiktu užsakymu šios Taisyklės tampa tarp Pirkėjo ir Pardavėjo sudaryta nuotoline paslaugų teikimo sutartimi ir yra abiem šalims privalomas teisinis dokumentas. Sutartis laikoma sudaryta, kai Pirkėjas suformuoja ir pateikia užsakymą, atlieka pradinį apmokėjimą ir Pardavėjas išsiunčia patvirtinimą, kad užsakymas priimtas. Pirkėjas supranta ir sutinka, kad prenumeratos užsakymas sukelia tęstinius ir periodiškai atsinaujinančius finansinius įsipareigojimus.","Pirkėjui nesuteikiama galimybė pateikti užsakymo, jeigu jis nėra susipažinęs su Taisyklėmis ir (ar) kitomis BRICKTIME elektroninėje parduotuvėje esančiomis tvarkomis, politikomis, ir (ar) su jomis nesutinka. Užsisakius paslaugas laikoma, jog Pirkėjas susipažino ir besąlygiškai sutiko su Taisyklėmis.","Pardavėjas pasilieka teisę vienašališkai pakeisti, taisyti ar papildyti Taisykles bei prenumeratų kainas. Esamiems prenumeratoriams apie pasikeitimus, galinčius turėti įtakos jų prenumeratos sąlygoms, pranešama el. paštu ne vėliau kaip prieš 14 kalendorinių dienų iki pakeitimų įsigaliojimo. Pirkėjui nesutinkant su pakeitimais, jis turi teisę nutraukti prenumeratą iki naujųjų Taisyklių ar kainų įsigaliojimo dienos.","Pardavėjas neprisiima jokios rizikos ar atsakomybės, jei Pirkėjas iš dalies ar visiškai nesusipažino su Taisyklėmis, nors jam tokia galimybė buvo suteikta.","Pardavėjas, atsižvelgdamas į sistemos techninius pajėgumus, turi teisę riboti registruotų Pirkėjų skaičių, taip pat be įspėjimo apriboti Pirkėjo naudojimąsi paslaugomis arba panaikinti registraciją ir (ar) prenumeratą, jeigu Pirkėjas pažeidžia Taisykles ar bando pakenkti svetainės saugumui.","Pardavėjas gali laikinai arba iš viso nutraukti BRICKTIME elektroninės parduotuvės veiklą dėl techninės priežiūros ar atnaujinimo darbų. Jei veikla ar paslaugų teikimas visiškai nutraukiamas, Pardavėjas įsipareigoja įvykdyti jau apmokėtus užsakymus arba proporcingai grąžinti pinigus už likusį ir nepasinaudotą prenumeratos laikotarpį. Įvykus force majeure aplinkybėms, Pardavėjas turi teisę sustabdyti sutarties vykdymą, apie tai pranešdamas Pirkėjui.","Pardavėjui priklauso visos autorinės teisės, teisės į duomenų bazes, prekių ženklus ir kitos intelektinės nuosavybės teisės į BRICKTIME interneto svetainės medžiagą. Pirkėjai gali naudotis šia medžiaga tik informaciniais ir asmeniniais nekomerciniais tikslais. Draudžiama be išankstinio raštiško sutikimo naudoti BRICKTIME pavadinimą, kopijuoti, platinti ar pritaikyti Intelektinės nuosavybės objektus komerciniais tikslais."]},{"id":"registracija-ir-duomenys","title":"2. Registracija ir asmens duomenų tvarkymas","body":["Pateikti užsakymus BRICKTIME elektroninėje parduotuvėje turi teisę tik registruoti Pirkėjai. Norėdamas tapti registruotu Pirkėju, asmuo privalo pateikti vardą, el. pašto adresą, sukurti slaptažodį bei susipažinti su Privatumo politika.","Pirkėjas yra atsakingas, kad jo pateikti duomenys būtų tikslūs, teisingi ir išsamūs, ir privalo juos nedelsdamas atnaujinti, jiems pasikeitus. Pirkėjas turi teisę bet kuriuo momentu keisti, papildyti ar panaikinti savo registraciją (paskyrą).","Registruodamasis Pirkėjas susikuria individualius prisijungimo duomenis ir įsipareigoja juos saugoti paslaptyje. Pirkėjas yra atsakingas už bet kuriuos veiksmus, atliekamus prisijungus jo el. pašto adresu ir slaptažodžiu. Praradus prisijungimo duomenis, būtina nedelsiant informuoti Pardavėją.","Norėdamas pateikti užsakymus, Pirkėjas privalo pateikti papildomus duomenis: telefono numerį, pristatymo adresą (arba pasirinkto paštomato duomenis) bei atsiskaitymo informaciją.","Pirkėjo asmens duomenys tvarkomi Pirkėjo identifikavimui, sutarties sudarymui ir vykdymui, apskaitos dokumentų išrašymui, lėšų nurašymo ir grąžinimo administravimui, įsiskolinimų ar materialinės žalos valdymui bei tiesioginei rinkodarai (tik gavus atskirą sutikimą).","Pardavėjas įsipareigoja laikytis konfidencialumo ir tvarkyti duomenis pagal BDAR bei Lietuvos Respublikos teisės aktų reikalavimus. Duomenys gali būti perduoti tik Pardavėjo partneriams, teikiantiems logistikos, mokėjimų surinkimo (pvz., Stripe, Satispay) bei buhalterinės apskaitos paslaugas.","Pardavėjas turi teisę apriboti, sustabdyti arba blokuoti Pirkėjo paskyrą, jei Pirkėjas pažeidžia Taisykles, laiku nesumoka prenumeratos mokesčio, tyčia gadina ar negrąžina LEGO® rinkinių. Apie tai Pirkėjas informuojamas el. paštu per 1 darbo dieną nuo ribojimų pritaikymo."]},{"id":"uzsakymas-kainos-apmokejimas","title":"3. Paslaugų užsakymas, kainos, apmokėjimo tvarka","body":["Paslaugų (prenumeratų) kainos nurodomos eurais su įskaičiuotais visais taikomais mokesčiais. Į prenumeratos kainą įskaičiuotas LEGO® rinkinių pristatymas ir grąžinimas, jei svetainėje nenurodyta kitaip.","Pardavėjas turi teisę keisti prenumeratų kainas – naujos kainos taikomos naujiems užsakymams nuo paskelbimo dienos. Esamiems prenumeratoriams pranešama el. paštu prieš 14 kalendorinių dienų iki kito periodinio mokėjimo nurašymo.","Pirkėjas atsiskaito mokėjimo kortelėmis, Apple Pay, Google Pay arba per Satispay programėlę. Mokėjimo operacijos atliekamos sertifikuoto paslaugos teikėjo saugiame serveryje – BRICKTIME sistemoje kortelės duomenys nesaugomi.","Įsigydamas prenumeratą, Pirkėjas suteikia teisę Pardavėjui ir mokėjimų partneriui „Stripe“ automatiškai ir reguliariai (kas mėnesį) nurašyti nustatyto dydžio prenumeratos mokestį be atskiro patvirtinimo kiekvieno nurašymo metu.","Paslaugų užsakymas patvirtinamas ir prenumerata aktyvuojama tik sėkmingai autorizavus pradinį mokėjimą. Jei periodinio mokėjimo dieną nepavyksta nurašyti mokesčio, „Stripe“ automatiškai kartoja bandymą; nepavykus – prenumerata laikinai sustabdoma. Jei mokėjimas neatliekamas per 5 kalendorines dienas, užsakymas anuliuojamas.","Atlikus mokėjimą, sistema automatiškai sugeneruoja ir el. paštu išsiunčia sąskaitą-faktūrą. Oficialus mokėjimų tvarkymo partneris – „Stripe“ (Stripe Technology Europe, Limited), užtikrinantis PCI-DSS duomenų saugumo standartus."]},{"id":"dovanu-kuponai","title":"4. Dovanų kuponų įsigijimas","body":["BRICKTIME svetainėje galima įsigyti elektroninius Dovanų kuponus, pateikiamus nurodytu el. paštu PDF ar kitu skaitmeniniu formatu. Kupono nominalas gali būti pasirinktas iš fiksuotų verčių arba įvedant bet kokią sumą.","Dovanų kuponas yra nevardinis ir suteikia teisę jį pateikusiam asmeniui apmokėti prenumeratos užsakymus už nurodytą sumą. Kuponas galioja 6 mėnesius nuo įsigijimo dienos, nebent kupone nurodyta kitaip.","Vienu kuponu galima atsiskaityti tik vieną kartą, po to kodas anuliuojamas. Jeigu užsakymo suma mažesnė už kupono nominalą, likusi suma nėra išgryninama, tačiau gali būti perkeliama į paskyros balansą ir panaudojama būsimiems mokesčiams dengti.","Dovanų kuponas negali būti keičiamas į grynuosius pinigus, pratęsiamas ar nemokamai išduodamas iš naujo, išskyrus atvejus, kai Pirkėjas pasinaudoja įstatymine teise atsisakyti sutarties per 14 dienų nuo įsigijimo (jei kuponas dar nepanaudotas).","Kuponu negali būti apmokamas joks kitas BRICKTIME dovanų kuponas. Kuponus klastoti, kopijuoti, dauginti ar naudoti neteisėtu būdu griežtai draudžiama – tokiu atveju Pardavėjas turi teisę panaikinti paskyrą ir anuliuoti kuponą.","Aktyvavus tęstinę prenumeratą Dovanų kuponu, pasibaigus kupono padengtam laikotarpiui, prenumerata automatiškai pratęsiama kitam mėnesiui. Norint išvengti tolesnių nurašymų, prenumeratą reikia atšaukti paskyroje prieš pasibaigiant kupono galiojimui."]},{"id":"paslaugu-teikimo-salygos","title":"5. Pagrindinės paslaugų teikimo (prenumeratų) sąlygos","body":["Prenumerata veikia kalendorinio mėnesio rotacijos principu: Pirkėjas per 1 mėnesį nuo aktyvavimo turi teisę pasirinkti, gauti ir nustatyta tvarka pasikeisti atitinkamo dydžio ir kategorijos LEGO® rinkinį pagal savo plano sąlygas.","BRICKTIME elektroninėje parduotuvėje galima rinktis prenumeratos lygius: „MĖGĖJAS“, „KŪRĖJAS“, „MEISTRAS“, „LEGENDA“, „MYSTERY BOX MĖGĖJAMS“ ir „MYSTERY BOX KŪRĖJAMS“. Aktualios sąlygos, keitimo terminai bei kainos pateikiami adresu bricktime.lt/subscribe.","Praėjus 1 mėnesiui nuo įsigijimo (ar paskutinio pratęsimo), prenumerata automatiškai pratęsiama kitam laikotarpiui, kol Pirkėjas jos neatšaukia ar nepakeičia. Pirkėjas gali bet kuriuo metu pakeisti savo prenumeratos planą savo paskyroje.","Sumažinus prenumeratos lygį, už einamąjį mėnesį sumokėti pinigai negrąžinami, o naujas lygis įsigalioja nuo kito atsiskaitymo laikotarpio; anksčiau gauti rinkiniai turi būti grąžinti iki naujo laikotarpio pradžios. Padidinus lygį, aukštesnis planas aktyvuojamas iš karto sumokėjus proporcingą kainos skirtumą, jei nėra negrąžintų rinkinių.","Pirkėjui per mėnesį leidžiama užsisakyti tik tokį LEGO® rinkinių kiekį ir tūrį, kurį numato jo prenumeratos planas. Priklausomai nuo plano, Pirkėjui suteikiamas virtualių „Briksių“ kreditų kiekis, leidžiantis užsisakyti papildomus rinkinius: S – 100, M – 200, L – 300, P – 400 briksių. Nutraukus prenumeratą, likę „Briksiai“ anuliuojami ir į pinigus nekeičiami.","LEGO® rinkinio patikra ir atsakomybė už trūkstamas detales. Pastebėjęs trūkstamą detalę, Pirkėjas privalo užpildyti trūkumų formą savo paskyroje. Priešingu atveju laikoma, kad rinkinys buvo pristatytas pilnos komplektacijos. Jei Pardavėjas, patikrinęs grąžintą rinkinį, užfiksuoja trūkumą, apie kurį Pirkėjas nepranešė, Pirkėjas atsako už jį ir įsipareigoja padengti detalės įsigijimo bei pristatymo kainą.","Pardavėjas, užfiksavęs trūkumus, el. paštu pateikia sąrašą ir apskaičiuotą žalą. Per 3 darbo dienas negrąžinus detalių ar nepateikus prieštaravimų, Pirkėjas suteikia sutikimą žalos sumą nurašyti automatiškai. Nepavykus nurašyti ar Pirkėjui atsisakius padengti nuostolius, Pardavėjas turi teisę sustabdyti prenumeratą. Detalių kainos nustatomos pagal bricklink.com ir lego.com duomenis.","Grąžinus rinkinį, Pardavėjas patikrina jį per 3 darbo dienas. Be trūkumų grąžintas rinkinys pažymimas Pirkėjo paskyroje ir suteikiama teisė rinktis kitą rinkinį.","Visi Pirkėjui pateikiami LEGO® rinkiniai, pakuotės ir instrukcijos išlieka Pardavėjo nuosavybe. Pirkėjui suteikiama tik laikina teisė asmeniniais, nekomerciniais tikslais naudotis gautais rinkiniais prenumeratos galiojimo metu – juos parduoti, pernuomoti, keisti ar perleisti tretiesiems asmenims draudžiama.","Pardavėjas atleidžiamas nuo atsakomybės už laikinus paslaugų sutrikimus, kilusius dėl Pirkėjo kaltės, trečiųjų šalių veiksmų ar force majeure aplinkybių."]},{"id":"rinkiniu-naudojimas","title":"6. LEGO® rinkinių naudojimo tvarka","body":["Prieš naudodamas LEGO® rinkinį, Pirkėjas privalo susipažinti su pridedama instrukcija ir jos laikytis. Pardavėjas neatsako už žalą, kilusią dėl to, kad Pirkėjas nesilaikė oficialių LEGO® saugumo ir naudojimo instrukcijų.","Rinkinys turi būti naudojamas rūpestingai, saugant jį nuo sugadinimo, praradimo ar perteklinio nusidėvėjimo, kad juo vėliau galėtų naudotis kiti Pirkėjai.","Grąžinamas rinkinys privalo būti visiškai išardytas į atskiras detales ir sudėtas į vieną maišiuką transportavimo dėžėje. Grąžinti pilnai ar dalinai sukonstruotų modelių negalima. Popierinės instrukcijos turi būti saugomos nuo sugadinimo ir grąžinamos kartu su rinkiniu, taip pat visi papildomi priedai (skyriklis, atsarginės detalės ir kt.).","Higienos ir saugumo reikalavimai. Draudžiama detales plauti indaplovėje, skalbimo mašinoje, virinti ar naudoti agresyvias valymo priemones. Jei rinkinys grąžinamas akivaizdžiai užterštas ar sugadintas, Pardavėjas turi teisę reikalauti papildomo valymo mokesčio arba taikyti žalos atlyginimo tvarką.","Pirkėjas turi teisę laikyti gautą rinkinį neribotą laiką, kol prenumerata aktyvi ir mokesčiai sėkmingai nurašomi. Gautus rinkinius ar jų dalis griežtai draudžiama skolinti, dovanoti, pernuomoti ar kitaip perleisti tretiesiems asmenims.","Pirkėjas, kurio vardu sudaryta sutartis, yra visiškai ir asmeniškai atsakingas už gautų rinkinių, pakuočių, instrukcijų bei detalių būklę, tinkamą naudojimą ir savalaikį grąžinimą."]},{"id":"sutarties-atsisakymas","title":"7. Sutarties atsisakymas, paslaugų keitimas ir atšaukimas","body":["Vadovaujantis Lietuvos Respublikos civilinio kodekso 6.228¹⁰ straipsniu, Pirkėjas (vartotojas) turi teisę per 14 dienų nuo sutarties sudarymo jos atsisakyti, nenurodydamas priežasties. Jei paslauga jau buvo pradėta teikti (rinkinys išsiųstas), Pirkėjas privalo savo lėšomis grąžinti jį idealios būklės, o Pardavėjas grąžina sumokėtus pinigus, atskaitęs sumą už faktiškai suteiktą laikotarpį bei siuntimo išlaidas.","Reguliarios prenumeratos nutraukimas (atšaukimas). Pirkėjas turi teisę bet kuriuo metu nemokamai atšaukti prenumeratą ateities periodams, savo paskyroje arba el. paštu info@bricktime.lt, likus ne mažiau kaip 3 darbo dienoms iki kito nurašymo. Nutraukus prenumeratą mėnesio viduryje, pinigai už likusias dienas negrąžinami, o paslauga galioja iki mėnesio pabaigos. Pasibaigus laikotarpiui, rinkinys turi būti grąžintas per 2 darbo dienas.","Jeigu Pardavėjas negali išsiųsti užsakyto rinkinio per 7 darbo dienas nuo apmokėjimo ir šalys nesutaria dėl alternatyvos, laikoma, kad paslauga negali būti suteikta – Pardavėjas grąžina visą sumokėtą sumą.","Pinigų grąžinimas atliekamas per 14 kalendorinių dienų nuo sutarties nutraukimo ir (ar) fizinio rinkinio grąžinimo bei patikros dienos, į tą pačią mokėjimo priemonę, kuria buvo atliktas pradinis mokėjimas.","Pradėjus, bet nebaigus ir neapmokėjus užsakymo proceso, nuotolinė paslaugų sutartis laikoma nesudaryta. Visiškai nutraukus prenumeratą ir (ar) ištrynus paskyrą, Pardavėjas nebeįsipareigoja išsaugoti užsakymų istorijos, „Briksių“ kreditų ar kitų duomenų – jie nėra perkeliami sukūrus naują paskyrą."]},{"id":"apsikeitimas-informacija","title":"8. Apsikeitimas informacija","body":["Pardavėjas visus pranešimus, susijusius su sutarties vykdymu, prenumeratos pratęsimu, mokėjimais ar pastebėtais detalių trūkumais, siunčia Pirkėjo registracijos ar užsakymo metu nurodytu el. paštu arba telefonu.","Pirkėjas visus pranešimus, pretenzijas ir klausimus siunčia oficialiais Pardavėjo kontaktais: el. paštu info@bricktime.lt arba telefonu +370 682 11695.","Šalys susitaria, kad el. paštu išsiųsti pranešimai laikomi gautais per 24 valandas nuo išsiuntimo, jei tai darbo diena, arba artimiausią darbo dieną, jei laiškas išsiųstas savaitgalį ar švenčių dienomis."]},{"id":"baigiamosios-nuostatos","title":"9. Baigiamosios nuostatos","body":["Šios Taisyklės sudarytos vadovaujantis Lietuvos Respublikos teisės aktais, kurie taikomi ir jų pagrindu kylantiems santykiams.","Atsiradus žalai, kaltoji šalis atlygina kitai šaliai tiesioginius nuostolius teisės aktų nustatyta tvarka. Nesutarimai sprendžiami derybų būdu, o nepavykus susitarti – Lietuvos Respublikos įstatymų nustatyta tvarka.","Kiekvienas Pirkėjas turi galimybę spręsti ginčus ne teismo tvarka: pirmiausia raštu kreiptis į Pardavėją (info@bricktime.lt), kuris įsipareigoja nemokamai išnagrinėti kreipimąsi ir pateikti motyvuotą atsakymą ne vėliau kaip per 14 kalendorinių dienų.","Jeigu Pardavėjo atsakymas netenkina arba nepateikiamas laiku, Pirkėjas turi teisę kreiptis į Valstybinę vartotojų teisių apsaugos tarnybą (Vilniaus g. 25, 01402 Vilnius, el. p. tarnyba@vvtat.lt, tel. +370 5 262 6751, www.vvtat.lt) arba užpildyti prašymo formą Elektroninio vartotojų ginčų sprendimo (EGS) platformoje adresu ec.europa.eu/odr."]}]$json$::jsonb);
